export function SiteIcon({
  name,
  ...props
}: { name: SiteIconName } & SVGProps<SVGSVGElement>) {
  const icon = ICONS[name];
  return (
    <svg
      viewBox={icon.viewBox}
      width="1em"
      height="1em"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {icon.paths.map((path, index) => (
        <path key={index} d={path.d} fill="currentColor" fillRule={path.fillRule} clipRule={path.clipRule} />
      ))}
    </svg>
  );
}
